async function privacy(){await readiness;if(!guide)return;const d=dialog('Your guide and privacy'),status=note(savedLabel(),'flow-answer');status.dataset.saveStatus='';status.setAttribute('role','status');d.append(secondary('Close',()=>d.close()),status,note('Confirmed guide answers are saved only after you choose saving. This local prototype keeps them for '+(session?.retentionDays||7)+' days from this browser session’s creation. No account or cross-device recovery. The browser holds a protected guest cookie. Anyone sharing this browser may resume; use a private visit on a shared device. Submitted chat and original text are not stored. Turning saving off stops future saves; use Delete to remove the existing saved copy.'));const label=node('label'),check=node('input');check.type='checkbox';check.checked=guide.preferences.saveSensitive;label.append(check,document.createTextNode(' Also save optional names, dates, medicine/pharmacy/provider notes and preparation notes'));check.onchange=()=>{guide.preferences.saveSensitive=check.checked;changed();};d.append(label,note('These notes are never automatically attached to AI. Removing this choice removes them from the next acknowledged save. Review its receipt before leaving.'));d.append(secondary('Start a new guide',()=>{d.close();newGuide();}),primary('Save this guide on this browser',async()=>{d.close();if(await enableSaving()&&active)render();}),secondary('Use this tab without further saving',()=>{guide.preferences.saveGuide=false;dirty=false;d.close();if(active)render();}),secondary('Review saved server version',()=>{d.close();void reviewServer();}),secondary('Delete saved guide and forget this browser',()=>{d.close();deletePrompt();}),secondary('Close',()=>d.close()));if(undoStack.length)d.append(secondary('Undo last recorded answer',()=>{d.close();undo();}));d.append(node('h3','Reported answers'));reviewRows(d);d.showModal();}
