async function ask(message){if(state.busy)return;if(!active){await readiness;P.visit(guide,'A01',false);}if(askMode==='answer')return interpret(message);state.busy=true;$('ask-send').disabled=true;addAsk('you',message);try{const topic=findGuideTopic(message);if(topic&&!aiConsent){addGuideAnswer(topic);rememberChat(message,topic.answer);return;}const status=busy($('ask-reading'),'Preparing your question…');const result=await agentRequest(message,m=>status.textContent=m);status.parentElement.remove();addAsk('daylight',result.acknowledgment,'','Daylight · live grounded agent');for(const f of result.facts)addAsk('daylight',f.text,f.source,'Daylight · reviewed source');if(result.patches.length){pending={...result,rawText:message,origin:guide.flow.node,confirmed:false};askMode='answer';renderAgentPanel();}rememberChat(message,result.acknowledgment);}catch(e){const msg=addAsk('daylight',e.name==='AbortError'?'Request canceled. No facts were recorded.':e.message,'','Daylight · reply unavailable');msg.append(secondary('Retry this question',()=>ask(message)));}finally{agentController=null;state.busy=false;$('ask-send').disabled=false;renderAskCanned();renderAgentPanel();}}

